/**
 * Kinds of opaque host identifiers the orchestrator handles, and checks that
 * route a wrong-kind ID to the tool that owns it (host enforcement instead of
 * the contract sentence "jobId, resultVersion, toolCallId and digest are
 * distinct opaque IDs").
 *
 * - jobId: `<adjective>-<color>-<animal>` from {@link DELEGATION_ID_WORDS}
 *   (generated by delegations.ts randomId).
 * - resultVersion / tool-artifact digest: sha256 hex (64 chars).
 * - toolCallId: provider-issued, no fixed shape — never inferred here.
 */

export const DELEGATION_ID_WORDS = {
  adjectives: ["brisk", "calm", "clever", "eager", "gentle", "keen", "lively", "nimble", "quiet", "steady"],
  colors: ["amber", "blue", "copper", "emerald", "indigo", "ivory", "silver", "teal", "violet", "white"],
  animals: ["badger", "falcon", "fox", "heron", "lynx", "otter", "owl", "panda", "sparrow", "wolf"],
} as const;

const alt = (words: readonly string[]) => words.join("|");
const JOB_ID_BODY = `(?:${alt(DELEGATION_ID_WORDS.adjectives)})-(?:${alt(DELEGATION_ID_WORDS.colors)})-(?:${alt(DELEGATION_ID_WORDS.animals)})`;
const JOB_ID_EXACT = new RegExp(`^${JOB_ID_BODY}$`);
const JOB_ID_ANYWHERE = new RegExp(`(?<![\\w-])${JOB_ID_BODY}(?![\\w-])`, "i");
const SHA256_EXACT = /^[0-9a-f]{64}$/i;
const SHA256_ANYWHERE = /(?<![0-9a-f])[0-9a-f]{64}(?![0-9a-f])/i;
/** Field names that only exist in host coordination records. */
const INTERNAL_FIELD = /\b(?:jobId|resultVersion|toolCallId|tool_call_id|messageId)\b/;

export type InternalIdKind = "jobId" | "resultVersion";

/** Kind of an ID that is NOT a tool_call_id, or undefined when it may be one. */
export function nonToolCallIdKind(id: string): InternalIdKind | undefined {
  const trimmed = id.trim();
  if (JOB_ID_EXACT.test(trimmed)) return "jobId";
  if (SHA256_EXACT.test(trimmed)) return "resultVersion";
  return undefined;
}

/** retrieve_tool_result answer for a jobId/resultVersion passed as a tool_call_id. */
export function wrongIdKindPointer(id: string, kind: InternalIdKind): string {
  return kind === "jobId"
    ? `ERROR id_kind_mismatch: "${id}" is a delegation jobId, not a tool_call_id. Read the worker result with delegation_read({id:"${id}"}); a raw worker tool artifact is delegation_read({id:"${id}", toolCallId, resultVersion}) with the toolCallId from its host manifest. Nothing was looked up.`
    : `ERROR id_kind_mismatch: "${id}" is a resultVersion/digest (sha256), not a tool_call_id. Pass it as resultVersion to delegation_read({id: jobId, toolCallId, resultVersion}); find the jobId with delegation_list. Nothing was looked up.`;
}

/** First internal coordination identifier in user-facing text, or undefined. */
export function findInternalId(text: string): string | undefined {
  return (
    JOB_ID_ANYWHERE.exec(text)?.[0] ?? SHA256_ANYWHERE.exec(text)?.[0] ?? INTERNAL_FIELD.exec(text)?.[0] ?? undefined
  );
}
